(h,count)=>{
if(h.disposed)throw Error('gpu-component-disposed');
if(!Number.isSafeInteger(count)||count<0||count>h.capacity)throw Error('gpu-component-capacity');
const {width,height}=h.canvas;
if(!Number.isSafeInteger(width)||width<=0||!Number.isSafeInteger(height)||height<=0)throw Error('gpu-component-viewport');
h.viewScratch[0]=h.logicalWidth??width;h.viewScratch[1]=h.logicalHeight??height;h.device.queue.writeBuffer(h.params,0,h.viewScratch);
const encoder=h.device.createCommandEncoder(),pass=encoder.beginRenderPass({colorAttachments:[{view:h.context.getCurrentTexture().createView(),loadOp:'clear',storeOp:'store',clearValue:{r:1,g:1,b:1,a:1}}]});
if(h.viewport)pass.setViewport(...h.viewport,0,1);
if(count>0){pass.setPipeline(h.pipeline);pass.setBindGroup(0,h.bindGroup);pass.setVertexBuffer(0,h.vertices);pass.draw(6,count);h.draws++;}
pass.end();h.device.queue.submit([encoder.finish()]);h.submits++;
}

